<script setup lang="ts">
import {computed,onMounted,ref,watch,nextTick} from 'vue';import {onBeforeRouteLeave,useRoute} from 'vue-router';
import StudioPlaceCreate from './StudioPlaceCreate.vue';import {getStudio,type StudioPayload} from './content-studio-api';
import {openingDisplay,operatingLabel,exhibitionOpeningApplies} from '../../shared/place-opening';import {placeCover,uniqueThemeIds} from '../../shared/studio-place-presentation';import './studio-place-list.css';
const route=useRoute(),payload=ref<StudioPayload|null>(null),creating=ref(false);let remembered:{q?:string;archived?:boolean;scroll?:number}={};try{remembered=JSON.parse(sessionStorage.getItem('studio.place-list')||'{}');}catch{}
const q=ref(typeof route.query.q==='string'?route.query.q:remembered.q||''),showArchived=ref(remembered.archived||false);
function remember(){try{sessionStorage.setItem('studio.place-list',JSON.stringify({q:q.value,archived:showArchived.value,scroll:window.scrollY}));}catch{}}
watch([q,showArchived],remember);onBeforeRouteLeave(()=>{remember();return true;});
onMounted(async()=>{payload.value=await getStudio();await nextTick();if(remembered.scroll&&!route.query.q)requestAnimationFrame(()=>window.scrollTo(0,remembered.scroll!));});
const places=computed(()=>Object.values(payload.value?.document.places||{}).filter(p=>(showArchived.value||!p.archivedAt)&&(!q.value||[p.id,p.name.zh,p.name.en,p.region.zh].join(' ').toLowerCase().includes(q.value.toLowerCase()))).sort((a,b)=>a.id.localeCompare(b.id)));
</script>
<template><div class="workspace-page studio-page place-list-page"><div class="workspace-title"><div><p class="kicker">地点</p><h1>地点内容</h1><p>查看已有资料与待完善内容，进入地点后按任务栏目编辑。</p></div><div class="workspace-actions"><button class="primary-action" @click="creating=true">＋ 新增地点</button><RouterLink class="button quiet" to="/studio/map">从地图查看</RouterLink></div></div><StudioPlaceCreate v-if="creating&&payload" :payload="payload" @cancel="creating=false" @created="payload.document=$event.document;payload.draftRevision=$event.draftRevision;payload.unpublishedPlaceIds=[...(payload.unpublishedPlaceIds||[]),$event.id];creating=false"/><label class="inline-check"><input type="checkbox" v-model="showArchived">显示归档地点（可进入恢复）</label><label class="studio-search"><span>查找地点</span><input v-model="q" placeholder="名称、区域或 WY 编号"></label><p class="list-result-count">{{places.length}} 个地点</p>
<div class="studio-place-grid"><RouterLink v-for="p in places" :key="p.id" :to="`/studio/places/${p.id}`" class="studio-place-card"><div class="studio-place-cover"><img v-if="placeCover(p)" :src="`/api/admin/visitor-content/media/${placeCover(p)!.fileName}`" :alt="placeCover(p)!.alt.zh" loading="lazy"><span v-else aria-hidden="true">{{p.category.includes('茶')?'茶':/展馆|博物/.test(p.category)?'馆':p.category.includes('停车')?'停':p.category.includes('服务')?'服':'地'}}</span></div><article><h2>{{p.name.zh||'未填写名称'}}</h2><p class="place-identity">{{p.id}} · {{p.region.zh||'未填写区域'}}</p><p class="place-category">{{p.category||'未分类'}}</p><div class="place-status-group"><span class="status-chip" :class="payload?.publishedPlaceIds?.includes(p.id)?'published':'hidden'">{{payload?.publishedPlaceIds?.includes(p.id)?'已有公开版本':'尚未公开'}}</span><span class="status-chip" :class="payload?.unpublishedPlaceIds?.includes(p.id)?'draft':'hidden'">{{payload?.unpublishedPlaceIds?payload.unpublishedPlaceIds.includes(p.id)?'本地有未发布修改':'与公开版本一致':'本地草稿 · 差异待核对'}}</span><span v-if="p.archivedAt" class="status-chip hidden">已归档</span></div><div class="place-status-details"><span v-if="exhibitionOpeningApplies(p)">运营 / 通行：{{operatingLabel(p.publicStatus,'zh')}}</span><span v-if="exhibitionOpeningApplies(p)">开放安排：{{openingDisplay(p,'zh').schedule}}</span><span>实地信息：{{p.trust.checkedInPerson?'已标记核验':'尚待核实'}}</span></div><p class="place-card-summary" :class="{missing:!p.summary.zh.trim()}">{{p.summary.zh||'未填写简介'}}</p><div class="visual-card-tags"><span v-for="id in uniqueThemeIds(p)" :key="id">{{payload?.document.themes.find(t=>t.id===id)?.name.zh||id}}</span></div><span class="place-edit-link">编辑地点 →</span></article></RouterLink></div><p v-if="payload&&!places.length">没有符合搜索条件的地点。可修改搜索或新建地点。</p></div></template>
